ch=input()
if len(ch)==1:
    if ch.islower():
        chup = ord(ch[0]) - 32
        print(chr(chup), end="")
    else:
        chup = ord(ch[0]) + 32
        print(chr(chup), end="")
elif ch[1:].isupper() or ch.isupper():
    chup = ord(ch[0])
    if chup>=65 and chup<=90:
        chup = chup+32
    else:
        chup = chup-32
    print(chr(chup), end="")

    for i in range(1,len(ch)):
        if ch[i]>="A" and ch[i]<="Z":
            asci = ord(ch[i])
            asci = asci + 32
            asci = chr(asci)
            print(asci, end="")
        else:
            asci = ord(ch[i])
            asci = asci - 32
            asci = chr(asci)
            print(asci, end="")
else:
    print(ch, end="")

