def create_list(word):
    list0 = []
    for letter in word:
        list0.append(letter)
    return list0

def check_caps(word):
    if len(word) == 1:
        return True
    return word[1:].isupper()

def assemble_list(l):
    word = "".join(l)
    return word

def caps(word):
    l = create_list(word)
    if check_caps(word):
        for i in range(0, len(l)):
            if l[i].isupper():
                l[i] = l[i].lower()
            else:
                l[i] = l[i].upper()
    word = assemble_list(l)
    return word

if __name__ == '__main__':
    word = input().strip()
    print(caps(word))

