def main():
    from sys import stdin, stdout
    s = stdin.readline()
    newline = ''
    if s.endswith('\n'):
        newline = '\n'
        s = s[:-1]
    if s[1:].upper() == s[1:]:
        s = s.swapcase()
    stdout.write(s + newline)
