def apply_caps_lock_rule(word):
    # Check if the word only contains uppercase letters
    if word.isupper():
        return word.swapcase()

    # Check if all letters except for the first one are uppercase
    if word[1:].isupper() or len(word) == 1:
        return word.swapcase()

    return word

