    word = "".join(l)
    return word

def caps(word):
    l = create_list(word)
    if check_caps(word) == 1:
        for i in range(0, len(l)):
            if l[i].islower():
                l[i] = l[i].upper()
            else:
                l[i] = l[i].lower()
    elif check_caps(word) == 2:
        for i in range(0, len(l)):
            if l[i].isupper():
                l[i] = l[i].lower()
