def toggle_case(s):
    if not s.isalpha():
        return s
    return s.lower() if s.isupper() else s.upper()

def apply_rule(word):
    if word.isupper() or (word[0].islower() and word[1:].isupper()) or len(word) == 1:
        return ''.join(toggle_case(c) for c in word)
    return word

